import numpy as np, torch, model
net=model.load(); w=torch.tensor(np.load('contrast_c5_out_act_k10.npy')); b=-17.6137
rng=np.random.default_rng(1); n=4096
z=torch.tensor(rng.standard_normal((n,2)),dtype=torch.float32); c=torch.tensor(rng.random(n),dtype=torch.float32)
def dec(dv=None, klo=0, khi=11, thr=0.0):
    x=z.clone(); fired=torch.zeros(n,dtype=torch.bool); sc=[]
    for k in range(20):
        t=torch.full((n,),1-k/20)
        v,a=net.velocity(x,t,c,('out_act',),count=False)
        s=a['out_act']@w+b; sc.append(s)
        f=(s>thr)&(klo<=k<khi); fired|=f
        if dv is not None: v=v+f[:,None].float()*torch.tensor(dv,dtype=torch.float32)
        x=x-v/20
    return x.numpy(), fired.numpy(), torch.stack(sc).numpy()
