import numpy as np, torch, model
net=model.load(); neg=model.negatives(); R=len(neg['uid'])
torch.manual_seed(2); N=6000
cs=torch.rand(N); xi=torch.randn(N,2)
th=np.radians(131); d=torch.tensor([np.cos(th),np.sin(th)],dtype=torch.float32); e=torch.tensor([-np.sin(th),np.cos(th)],dtype=torch.float32)
def relu(z): return torch.clamp(z,min=0)
def run(g=None,thr=None,klo=0,khi=0):
    x=xi.clone()
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v=net.velocity(x,t,cs,(),count=False)[0]
            if g is not None and klo<=k<khi:
                thk=thr[k] if isinstance(thr,dict) else thr
                m=((x@d)>thk).float()[:,None]
                v=v+m*g(x)
            x=x-v/20
    return x.numpy()
a0=run()
def bads(a,rows):
    out=np.zeros(N,bool)
    for i in rows: out|=np.asarray(model.in_basin(i,a)).astype(bool)
    return out
b0=bads(a0,[8,10]); o0=bads(a0,[i for i in range(R) if i not in (8,10)])
c=cs.numpy()
def between(a):
    # distance to nearest a0 sample with |c diff|<0.03
    res=np.zeros(N)
    for j in range(0,N,500):
        D=np.linalg.norm(a[j:j+500,None]-a0[None],axis=2)+ (np.abs(c[j:j+500,None]-c[None])>0.03)*1e3
        res[j:j+500]=D.min(1)
    return (res>0.5).mean()
print('base bad',b0.mean(),'other',o0.mean())
def tent(lam,w):
    def g(x):
        s=x@e
        f=relu(s)-2*relu(s-w)+relu(s-2*w)-(relu(-s)-2*relu(-s-w)+relu(-s-2*w))
        return -20*lam*f[:,None]*e[None]
    return g
def const(gam):
    return lambda x: -20*gam*e[None].expand(x.shape[0],2)
cfgs=[]
for (klo,khi) in [(6,12),(8,13),(10,14)]:
    for thr in [0.3,0.6,0.9]:
        for lam in [0.1,0.2]:
            cfgs.append(('tent',lam,0.6,thr,klo,khi))
        for gam in [0.05,-0.05]:
            cfgs.append(('const',gam,0,thr,klo,khi))
for cf in cfgs:
    kind,p,w,thr,klo,khi=cf
    g=tent(p,w) if kind=='tent' else const(p)
    a=run(g,thr,klo,khi)
    b=bads(a,[8,10]); o=bads(a,[i for i in range(R) if i not in (8,10)])
    mv=np.linalg.norm(a-a0,axis=1)>0.3
    print(cf,'bad',round(b.mean(),4),'fall%',round(1-b.mean()/b0.mean(),2),'drift_nonbad',round((mv&~b0).mean(),4),'other+',round(o.mean()-o0.mean(),4),'between',round(between(a),4))

